function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 entries.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Every entry of nums is 0 or 1.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  return null;
}

