function minKBitFlips(nums, k) {
  // Each window is flipped at most once and order does not matter: try every subset of windows.
  const windows = nums.length - k + 1;
  if (windows > 20) {
    // Too many subsets: invert each forced window entry by entry instead.
    const bits = nums.slice();
    let count = 0;
    for (let i = 0; i < bits.length; i++) {
      if (bits[i] === 1) continue;
      if (i + k > bits.length) return -1;
      for (let j = i; j < i + k; j++) bits[j] ^= 1;
      count++;
    }
    return count;
  }
  let best = -1;
  for (let mask = 0; mask < (1 << windows); mask++) {
    const bits = nums.slice();
    let used = 0;
    for (let w = 0; w < windows; w++) {
      if (!(mask & (1 << w))) continue;
      used++;
      for (let j = w; j < w + k; j++) bits[j] ^= 1;
    }
    if (bits.every(b => b === 1) && (best === -1 || used < best)) best = used;
  }
  return best;
}

