function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  let k;
  if (size === 'large') {
    const pick = rand();
    k = pick < 0.3 ? 1 + Math.floor(rand() * 5) : pick < 0.7 ? 1 + Math.floor(rand() * 200) : 1 + Math.floor(rand() * n);
  } else {
    k = 1 + Math.floor(rand() * n);
  }
  let nums;
  if (rand() < 0.6) {
    // Start from all ones and apply random windows so the input is solvable.
    nums = new Array(n).fill(1);
    const moves = Math.floor(rand() * (size === 'large' ? 400 : 6));
    for (let m = 0; m < moves; m++) {
      const start = Math.floor(rand() * (n - k + 1));
      for (let j = start; j < start + k; j++) nums[j] ^= 1;
    }
  } else {
    const density = rand();
    nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  }
  return [nums, k];
}
